 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    placements = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            if square <= cells:
                placements.append((square, 1))
            # L triominoes are labeled by the location of the missing corner:
            # top-left=2, top-right=3, bottom-left=4, bottom-right=5.
            for k, missing in enumerate(((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1))):
                piece = square - {missing}
                if piece <= cells:
                    placements.append((piece, k + 2))

    by_cell = {p: [] for p in cells}
    for shape, color in placements:
        for p in shape:
            by_cell[p].append((shape, color))

    def search(remaining, chosen):
        if not remaining:
            return chosen
        p = min(remaining, key=lambda q: sum(shape <= remaining for shape, _ in by_cell[q]))
        for shape, color in by_cell[p]:
            if shape <= remaining:
                result = search(remaining - shape, chosen + [(shape, color)])
                if result is not None:
                    return result
        return None

    tiling = search(cells, [])
    if tiling is None:
        raise ValueError('No valid square/L-triomino tiling')
    out = [[0 for _ in range(w)] for _ in range(h)]
    for shape, color in tiling:
        for r, c in shape:
            out[r][c] = color
    return out
